changeSet.sql:
-- Only Rosstat defines the region catalog. Remove former BenzUp-only additions and their dependent data. UPDATE regional_price_keys SET current_observation_id = NULL WHERE region_id IN (SELECT id FROM regions WHERE left(code, 7) = 'BENZUP_');
DELETE FROM regional_price_observations observation USING regional_price_keys price_key, regions region WHERE observation.price_key_id = price_key.id AND price_key.region_id = region.id AND left(region.code, 7) = 'BENZUP_';
DELETE FROM regional_price_keys price_key USING regions region WHERE price_key.region_id = region.id AND left(region.code, 7) = 'BENZUP_';
DELETE FROM benzup_measurements measurement USING regions region WHERE measurement.region_id = region.id AND left(region.code, 7) = 'BENZUP_';
DELETE FROM benzup_daily_prices daily USING regions region WHERE daily.region_id = region.id AND left(region.code, 7) = 'BENZUP_';
WITH removed AS ( DELETE FROM regions WHERE left(code, 7) = 'BENZUP_' RETURNING id ) UPDATE archive_state SET revision = revision + 1, updated_at = CURRENT_TIMESTAMP WHERE id = 1 AND EXISTS (SELECT 1 FROM removed);
